package net.civeira.phylax.features.access.oauthclient.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.features.access.oauthclient.domain.event.OauthClientEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class OauthClientEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<OauthClientEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final OauthClient entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
